package com.zenix.musicplayer;

import android.content.Context;
import android.util.AtomicFile;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

final class BackupManager {
    private final Context context;private final ZenixRuntime runtime;private final ListeningStats stats;private final AtomicFile journal;
    private JSONObject pending;private String token;private String failure="";
    BackupManager(Context context,ZenixRuntime runtime,ListeningStats stats){this.context=context;this.runtime=runtime;this.stats=stats;journal=new AtomicFile(new File(context.getFilesDir(),"backup-restore.json"));try{JSONObject saved=readJournal();if(saved!=null&&saved.optBoolean("pending")){synchronized(stats){runtime.store.backupLocked(()->{writeState(saved.getJSONObject("before"),sections(saved.getJSONArray("sections")));journal.delete();return true;});}}}catch(Exception e){failure="恢复快照无法恢复，已保留文件："+Json.message(e);runtime.store.stopWrites(failure);}}
    private JSONObject readJournal()throws Exception{try{return ProtectedJson.decode(new JSONObject(new String(SourceHttp.bounded(journal.openRead(),32*1024*1024),StandardCharsets.UTF_8)));}catch(FileNotFoundException e){return null;}}
    private void writeJournal(JSONObject value)throws Exception{byte[] bytes=ProtectedJson.encode(value.toString()).getBytes(StandardCharsets.UTF_8);if(bytes.length>32*1024*1024)throw new Exception("恢复快照过大，请分批恢复资料");FileOutputStream output=null;try{output=journal.startWrite();output.write(bytes);journal.finishWrite(output);}catch(Exception e){if(output!=null)journal.failWrite(output);throw e;}}
    private Set<String> sections(JSONArray values)throws Exception{if(values==null||values.length()==0)throw new Exception("请选择要备份或恢复的资料");Set<String> result=new LinkedHashSet<>();for(int i=0;i<values.length();i++){String key=values.getString(i);if(!BackupFormat.SECTIONS.contains(key))throw new Exception("资料类型无效");result.add(key);}return result;}
    private JSONObject capture(Set<String> selected)throws Exception{runtime.store.ensureReadable();JSONObject state=runtime.store.readKeys("personal","profile","appearance");if(!state.has("profile"))Json.put(state,"profile",new JSONObject());if(!state.has("appearance")||state.isNull("appearance"))Json.put(state,"appearance",Json.obj("completed",true,"background",JSONObject.NULL));Json.put(state,"stats",selected.contains("stats")?stats.exportAll():Json.obj("startedAt",System.currentTimeMillis(),"days",new JSONObject(),"tracks",new JSONObject()));return state;}
    private void writeState(JSONObject value,Set<String> sections)throws Exception{JSONObject changes=new JSONObject();if(sections.stream().anyMatch(key->List.of("liked","favorites","playlists","history").contains(key)))Json.put(changes,"personal",value.getJSONObject("personal"));if(sections.contains("profile"))Json.put(changes,"profile",value.getJSONObject("profile"));else if(sections.contains("appearance")){JSONObject profile=runtime.store.object("profile");Json.put(profile,"cardTransparency",value.getJSONObject("profile").optDouble("cardTransparency",0));Json.put(changes,"profile",profile);}if(sections.contains("appearance"))Json.put(changes,"appearance",value.getJSONObject("appearance"));runtime.store.replaceAtomic(changes);if(sections.contains("stats"))stats.replaceAll(value.getJSONObject("stats"));}
    private JSONObject selected(JSONObject state,Set<String> sections)throws Exception{JSONObject result=new JSONObject();if(sections.stream().anyMatch(key->List.of("liked","favorites","playlists","history").contains(key)))Json.put(result,"personal",state.getJSONObject("personal"));for(String key:List.of("profile","appearance","stats"))if(sections.contains(key))Json.put(result,key,state.getJSONObject(key));if(sections.contains("appearance"))Json.put(result,"cardTransparency",state.getJSONObject("profile").optDouble("cardTransparency",0));return result;}
    synchronized JSONObject preview(String text)throws Exception{pending=BackupFormat.decode(text);token=UUID.randomUUID().toString();JSONObject result=BackupFormat.preview(pending);Json.put(result,"token",token);return result;}
    synchronized String create(JSONObject args)throws Exception{if(!failure.isEmpty())throw new Exception(failure);Set<String> selected=sections(args.optJSONArray("sections"));JSONObject state=capture(selected),payload=Json.obj("personal",new JSONObject());for(String key:List.of("liked","favorites","playlists","history"))if(selected.contains(key))Json.put(payload.getJSONObject("personal"),key,state.getJSONObject("personal").opt(key));if(selected.contains("profile"))Json.put(payload,"profile",BackupFormat.profile(state.getJSONObject("profile")));if(selected.contains("stats"))Json.put(payload,"stats",state.getJSONObject("stats"));if(selected.contains("appearance")){JSONObject appearance=Json.obj("transparency",args.optJSONObject("browser")==null?20:args.getJSONObject("browser").optDouble("transparency",20));JSONObject background=state.getJSONObject("appearance").optJSONObject("background");if(background!=null&&args.optBoolean("includeBackground")){String kind=background.optString("kind");if(kind.equals("video")&&!args.optBoolean("includeVideo"))throw new Exception("视频背景需要单独勾选");File file=ownedBackground(background.getString("url"));byte[] bytes=SourceHttp.bounded(new FileInputStream(file),(kind.equals("video")?32:12)*1024*1024);media(bytes,kind);Json.put(appearance,"media",Json.obj("kind",kind,"name",background.optString("name","自定义背景"),"base64",Base64.encodeToString(bytes,Base64.NO_WRAP)));}Json.put(payload,"appearance",appearance);}return BackupFormat.encode(payload);}
    private File ownedBackground(String url)throws Exception{File file=new File(url).getCanonicalFile(),folder=new File(context.getFilesDir(),"background").getCanonicalFile();if(!file.getParentFile().equals(folder)||!file.isFile())throw new Exception("背景文件不可读取");return file;}
    static String media(byte[] bytes,String kind)throws Exception{String extension="";if(bytes.length>=12){if(bytes[0]==(byte)137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71)extension=".png";else if(bytes[0]==(byte)255&&bytes[1]==(byte)216&&bytes[2]==(byte)255)extension=".jpg";else if(new String(bytes,0,6,StandardCharsets.US_ASCII).matches("GIF8[79]a"))extension=".gif";else if(new String(bytes,0,4,StandardCharsets.US_ASCII).equals("RIFF")&&new String(bytes,8,4,StandardCharsets.US_ASCII).equals("WEBP"))extension=".webp";else if(new String(bytes,4,4,StandardCharsets.US_ASCII).equals("ftyp"))extension=".mp4";else if(bytes[0]==26&&bytes[1]==69&&bytes[2]==(byte)223&&bytes[3]==(byte)163)extension=".webm";}if(extension.isEmpty()||kind.equals("video")!=List.of(".mp4",".webm").contains(extension)||bytes.length>(kind.equals("video")?32:12)*1024*1024)throw new Exception("备份背景只支持常见图片（12 MiB 内）及 MP4/WebM（32 MiB 内）");return extension;}
    synchronized Object invoke(JSONObject args)throws Exception{
        if(!failure.isEmpty())throw new Exception(failure);
        switch(args.optString("operation")){
            case "backupInfo":{JSONObject appearance=runtime.store.object("appearance"),background=appearance==null?null:appearance.optJSONObject("background");long bytes=0;if(background!=null)try{bytes=ownedBackground(background.optString("url")).length();}catch(Exception ignored){}return Json.obj("undoAvailable",readJournal()!=null,"backgroundBytes",bytes,"statsBytes",context.getDatabasePath("listening-stats.db").length(),"profileBytes",runtime.store.object("profile").toString().getBytes(StandardCharsets.UTF_8).length,"metadataBytes",runtime.store.object("personal").toString().getBytes(StandardCharsets.UTF_8).length,"backgroundKind",background==null?JSONObject.NULL:background.optString("kind"));}
            case "backupDiscard":pending=null;token=null;return true;
            case "backupApply":synchronized(stats){return runtime.store.backupLocked(()->{
                if(pending==null||!args.optString("token").equals(token))throw new Exception("恢复预览已失效，请重新选择备份");Set<String> selected=sections(args.optJSONArray("sections"));JSONObject before=capture(selected),after=Json.copy(before),merged=BackupFormat.mergePersonal(before.getJSONObject("personal"),pending.getJSONObject("personal"),selected,runtime.store.array("localTracks"));Json.put(after,"personal",merged.getJSONObject("personal"));
                if(selected.contains("profile")&&pending.has("profile")){JSONObject profile=Json.copy(before.getJSONObject("profile")),incoming=pending.getJSONObject("profile");for(Iterator<String> keys=incoming.keys();keys.hasNext();){String key=keys.next();Json.put(profile,key,incoming.opt(key));}if(!incoming.has("bio")&&incoming.has("tagline"))Json.put(profile,"bio",incoming.opt("tagline"));Json.put(after,"profile",profile);}
                if(selected.contains("stats")&&pending.has("stats"))Json.put(after,"stats",BackupFormat.mergeStats(before.getJSONObject("stats"),pending.getJSONObject("stats")));
                if(selected.contains("appearance")&&pending.has("appearance")){JSONObject value=pending.getJSONObject("appearance"),appearance=Json.copy(before.getJSONObject("appearance")),media=value.optJSONObject("media");Json.put(after.getJSONObject("profile"),"cardTransparency",value.optDouble("transparency"));Json.put(appearance,"transparency",value.optDouble("transparency"));if(media!=null){byte[] bytes=Base64.decode(media.getString("base64"),Base64.DEFAULT);String extension=media(bytes,media.getString("kind"));File directory=new File(context.getFilesDir(),"background");directory.mkdirs();File file=new File(directory,"backdrop-"+UUID.randomUUID()+extension);try(FileOutputStream output=new FileOutputStream(file)){output.write(bytes);}Json.put(appearance,"background",Json.obj("kind",media.getString("kind"),"name",media.getString("name"),"url",file.getAbsolutePath()));Json.put(appearance,"completed",true);}Json.put(after,"appearance",appearance);}
                JSONObject saved=Json.obj("pending",true,"before",before,"after",after,"sections",new JSONArray(selected));writeJournal(saved);
                try{writeState(after,selected);Json.put(saved,"pending",false);writeJournal(saved);}catch(Exception e){try{writeState(before,selected);journal.delete();}catch(Exception rollback){failure="恢复中断，快照已保留；请重启后解决存储问题";runtime.store.stopWrites(failure);}throw e;}
                pending=null;token=null;runtime.emit();merged.remove("personal");Json.put(merged,"undoAvailable",true);return merged;
            });}
            case "backupUndo":synchronized(stats){return runtime.store.backupLocked(()->{JSONObject saved=readJournal();if(saved==null||saved.optBoolean("pending"))throw new Exception("没有可撤销的恢复");Set<String> selected=sections(saved.getJSONArray("sections"));JSONObject current=capture(selected);if(!BackupFormat.canonical(selected(current,selected)).equals(BackupFormat.canonical(selected(saved.getJSONObject("after"),selected))))throw new Exception("恢复后资料已改变，暂不能整体撤销，以免覆盖新资料；恢复前快照仍保留");JSONObject undo=Json.copy(saved);Json.put(undo,"pending",true);Json.put(undo,"before",current);writeJournal(undo);try{writeState(saved.getJSONObject("before"),selected);journal.delete();}catch(Exception e){writeState(current,selected);writeJournal(saved);throw e;}runtime.emit();return Json.obj("undoAvailable",false);});}
            case "backupRelink":synchronized(stats){return runtime.store.backupLocked(()->{JSONObject personal=runtime.store.object("personal");int[] count={0};relink(personal,runtime.store.array("localTracks"),count);runtime.store.replaceAtomic(Json.obj("personal",personal));runtime.emit();return Json.obj("linked",count[0]);});}
            default:throw new Exception("未知资料备份操作");
        }
    }
    private void relink(Object value,JSONArray local,int[] count)throws Exception{if(value instanceof JSONArray){JSONArray array=(JSONArray)value;for(int i=0;i<array.length();i++){Object child=array.get(i);JSONObject song=child instanceof JSONObject?(JSONObject)child:null;if(song!=null&&song.has("title")&&song.optString("source").equals("local")&&song.optString("availability").equals("unavailable")){JSONObject restored=BackupFormat.restoreTrack(song,local);if(restored.optString("availability").equals("playable"))count[0]++;array.put(i,restored);}else relink(child,local,count);}}else if(value instanceof JSONObject){JSONObject object=(JSONObject)value;for(Iterator<String> keys=object.keys();keys.hasNext();){String key=keys.next();Object child=object.get(key);if(key.equals("track")&&child instanceof JSONObject){JSONObject song=(JSONObject)child;if(song.optString("source").equals("local")&&song.optString("availability").equals("unavailable")){JSONObject restored=BackupFormat.restoreTrack(song,local);if(restored.optString("availability").equals("playable"))count[0]++;Json.put(object,key,restored);if(object.has("playedAt"))Json.put(object,"id",restored.optString("id"));}else relink(child,local,count);}else relink(child,local,count);}}}
}
